def handle_validate_email_mock(params: dict) -> tuple[int, dict]:
    email = params.get("email")
    if not isinstance(email, str):
        return 400, {"valid": False, "error": "invalid email"}
    # Mocking validation logic: just check for @
    if "@" not in email:
        return 400, {"valid": False, "error": "invalid email"}

    # Simulate normalization (domain part lowercased)
    parts = email.split("@")
    if len(parts) != 2:
        return 400, {"valid": False, "error": "invalid email"}

    normalized = parts[0] + "@" + parts[1].lower()
    return 200, {"valid": True, "email": normalized}

print(handle_validate_email_mock({"email": "Test@EXAMPLE.com"}))
print(handle_validate_email_mock({"email": "invalid"}))
print(handle_validate_email_mock({}))
EOF
